create table public.scheduled_jobs(id uuid primary key default gen_random_uuid(),job_key text not null unique,job_type text not null check(job_type in('BASELINE_FORECAST','FORECAST_OUTCOME','FORECAST_PERFORMANCE')),scheduler_version text not null,interval_seconds integer not null check(interval_seconds>=60),lease_seconds integer not null default 300,enabled boolean not null default true,status text not null check(status in('HEALTHY','DEGRADED','FAILED','PAUSED')),next_run_at timestamptz not null,last_started_at timestamptz,last_successful_run_at timestamptz,last_heartbeat_at timestamptz,locked_at timestamptz,locked_by text,consecutive_failures integer not null default 0,last_error text,rate_limit_budget jsonb not null default'{}',metrics jsonb not null default'{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.scheduled_job_runs(id uuid primary key default gen_random_uuid(),job_id uuid not null references public.scheduled_jobs(id),scheduled_for timestamptz not null,status text not null check(status in('RUNNING','SUCCEEDED','FAILED')),attempt integer not null,worker_id text not null,started_at timestamptz not null default now(),heartbeat_at timestamptz not null default now(),finished_at timestamptz,records_processed integer not null default 0,metrics jsonb not null default'{}',provider_budget_used jsonb not null default'{}',error text,unique(job_id,scheduled_for,attempt));
create or replace function public.claim_forecast_scheduled_job(p_worker_id text,p_now timestamptz default now())returns setof public.scheduled_job_runs language plpgsql security definer set search_path=public as $$declare j public.scheduled_jobs;r public.scheduled_job_runs;slot timestamptz;begin select*into j from scheduled_jobs where enabled and status<>'PAUSED' and next_run_at<=p_now and(locked_at is null or locked_at+(lease_seconds||' seconds')::interval<p_now)order by next_run_at for update skip locked limit 1;if not found then return;end if;slot=j.next_run_at;update scheduled_jobs set locked_at=p_now,locked_by=p_worker_id,last_started_at=p_now,last_heartbeat_at=p_now,updated_at=p_now where id=j.id;insert into scheduled_job_runs(job_id,scheduled_for,status,attempt,worker_id)values(j.id,slot,'RUNNING',j.consecutive_failures+1,p_worker_id)returning*into r;return next r;end$$;
create or replace function public.heartbeat_forecast_scheduled_job(p_run_id uuid,p_worker_id text,p_now timestamptz default now())returns void language plpgsql security definer set search_path=public as $$begin update scheduled_job_runs set heartbeat_at=p_now where id=p_run_id and worker_id=p_worker_id and status='RUNNING';update scheduled_jobs j set last_heartbeat_at=p_now,updated_at=p_now from scheduled_job_runs r where r.id=p_run_id and r.job_id=j.id and r.worker_id=p_worker_id and j.locked_by=p_worker_id;end$$;
create or replace function public.finish_forecast_scheduled_job(p_run_id uuid,p_worker_id text,p_success boolean,p_records integer,p_metrics jsonb,p_error text,p_now timestamptz default now())returns void language plpgsql security definer set search_path=public as $$declare j scheduled_jobs;r scheduled_job_runs;failures int;begin select*into r from scheduled_job_runs where id=p_run_id and worker_id=p_worker_id for update;if not found then raise exception'Run lease not owned';end if;select*into j from scheduled_jobs where id=r.job_id for update;failures=case when p_success then 0 else j.consecutive_failures+1 end;update scheduled_job_runs set status=case when p_success then'SUCCEEDED'else'FAILED'end,finished_at=p_now,heartbeat_at=p_now,records_processed=p_records,metrics=coalesce(p_metrics,'{}'),error=p_error where id=r.id;update scheduled_jobs set status=case when p_success then'HEALTHY'when failures>=3 then'FAILED'else'DEGRADED'end,next_run_at=case when p_success then r.scheduled_for+(interval_seconds||' seconds')::interval else p_now+(least(3600,30*power(2,greatest(0,failures-1)))||' seconds')::interval end,last_successful_run_at=case when p_success then p_now else last_successful_run_at end,last_heartbeat_at=p_now,locked_at=null,locked_by=null,consecutive_failures=failures,last_error=p_error,metrics=coalesce(p_metrics,'{}'),updated_at=p_now where id=j.id;end$$;
insert into public.scheduled_jobs(job_key,job_type,scheduler_version,interval_seconds,lease_seconds,status,next_run_at,rate_limit_budget)values('baseline-forecast-5m','BASELINE_FORECAST','forecast-scheduler-v1',300,240,'HEALTHY',now(),'{"databaseRows":10000}'),('forecast-outcomes-1m','FORECAST_OUTCOME','forecast-scheduler-v1',60,240,'HEALTHY',now(),'{"databaseRows":5000}'),('forecast-performance-15m','FORECAST_PERFORMANCE','forecast-scheduler-v1',900,300,'HEALTHY',now(),'{"databaseRows":10000}')on conflict(job_key)do nothing;
alter table public.scheduled_jobs enable row level security;alter table public.scheduled_job_runs enable row level security;create policy "public read scheduler status" on public.scheduled_jobs for select using(true);create policy "public read scheduler runs" on public.scheduled_job_runs for select using(true);grant select on public.scheduled_jobs,public.scheduled_job_runs to anon,authenticated;grant all on public.scheduled_jobs,public.scheduled_job_runs to service_role;revoke all on function public.claim_forecast_scheduled_job(text,timestamptz),public.heartbeat_forecast_scheduled_job(uuid,text,timestamptz),public.finish_forecast_scheduled_job(uuid,text,boolean,integer,jsonb,text,timestamptz)from public,anon,authenticated;grant execute on function public.claim_forecast_scheduled_job(text,timestamptz),public.heartbeat_forecast_scheduled_job(uuid,text,timestamptz),public.finish_forecast_scheduled_job(uuid,text,boolean,integer,jsonb,text,timestamptz)to service_role;
alter table public.ingestion_runs drop constraint if exists ingestion_runs_job_kind_check;alter table public.ingestion_runs add constraint ingestion_runs_job_kind_check check(job_kind in('stock_quotes','wallet_transactions','wallet_discovery','crypto_market','wallet_pnl','wallet_evidence','fast_flow','wallet_clustering','jackpot_collector','jackpot_outcomes','market_events','paper_eligibility','paper_execution','paper_exits','paper_valuation','performance','fx','qualification','data_gap_closure','simulation','historical_replay','forecast_catalyst','expert_knowledge','baseline_forecast','forecast_performance','forecast_scheduler','forecast_outcomes'));
